// Lookup helpers
export function getVocabByGrade(grade) { return VOCABULARY_CARDS.filter(c => c.grade === grade); }
export function getVocabByDomain(domain) { return VOCABULARY_CARDS.filter(c => c.domain === domain); }
export function getVocabByGradeAndDomain(grade, domain) { return VOCABULARY_CARDS.filter(c => c.grade === grade && c.domain === domain); }
export function getVocabByRitBand(ritBand) { return VOCABULARY_CARDS.filter(c => c.ritBand === ritBand); }
